        Screen(TermuxActivity activity,String directory,String selected){a=activity;project=directory;agent=selected;backend=q->AgentInstructions.request(a,q);}
        String t(String ru,String en){return AgentInstructionsUi.tr(a,ru,en);}
        int dp(int x){return WorkspaceDialogs.dp(a,x);}
        LinearLayout column(){LinearLayout v=new LinearLayout(a);v.setOrientation(LinearLayout.VERTICAL);return v;}
        TextView text(String s){TextView v=new TextView(a);v.setText(s);v.setTextColor(WorkspaceDialogs.TEXT);v.setTextSize(13);v.setPadding(dp(6),dp(6),dp(6),dp(6));v.setTextIsSelectable(true);return v;}
        TextView button(LinearLayout parent,String s,Runnable action){TextView v=WorkspaceDialogs.action(a,s,0);v.setOnClickListener(w->{if(!busy&&!closed)action.run();});parent.addView(v,new LinearLayout.LayoutParams(-1,-2));return v;}
