        JSONObject fields(JSONObject q,Object... pairs){try{for(int n=0;n<pairs.length;n+=2)q.put((String)pairs[n],pairs[n+1]);return q;}catch(JSONException e){throw new IllegalStateException(e);}}
        void show(){
            frame=new AgentManagerLayout(a);root=frame;selectors=column();frame.content.addView(selectors);status=AgentManagerLayout.status(a);status.setTextColor(WorkspaceDialogs.TEXT);status.setTextSize(13);status.setVisibility(View.GONE);frame.content.addView(status);
            rows=column();frame.content.addView(rows,new LinearLayout.LayoutParams(-1,0,1));
            TextView add=WorkspaceDialogs.action(a,t("Добавить","Add"),0);add.setOnClickListener(v->{if(!busy&&!closed)add(false,null);});
            TextView refresh=WorkspaceDialogs.action(a,t("Обновить список","Refresh list"),0);refresh.setOnClickListener(v->{if(!busy&&!closed)load();});
            TextView close=WorkspaceDialogs.action(a,t("Закрыть","Close"),0);close.setOnClickListener(v->{if(!busy)dialog.dismiss();});frame.actions(add,refresh,close);
            dialog=new android.app.AlertDialog(a,com.termux.R.style.WorkspaceDialog){@Override public void cancel(){if(!busy)super.cancel();}@Override public void onBackPressed(){if(!busy)super.onBackPressed();}};
            dialog.setTitle(label(a));((android.app.AlertDialog)dialog).setView(root,0,0,0,0);dialog.setOnDismissListener(d->{closed=true;for(Dialog child:new java.util.ArrayList<>(children))child.dismiss();children.clear();if(browser!=null)browser.close();discard();worker.shutdown();main.removeCallbacksAndMessages(null);});dialog.show();AgentManagerLayout.keyboard(dialog);select();load();
        }
        void choices(LinearLayout parent,String[] names,int selected,Consumer<Integer> action){LinearLayout row=new LinearLayout(a);for(int i=0;i<names.length;i++){final int index=i;TextView v=WorkspaceDialogs.action(a,names[i],0);v.setSingleLine(true);v.setSelected(i==selected);v.setBackground(WorkspaceDialogs.background(a,i==selected));v.setTextColor(i==selected?WorkspaceDialogs.ACCENT:WorkspaceDialogs.TEXT);v.setTypeface(null,i==selected?Typeface.BOLD:Typeface.NORMAL);v.setContentDescription(names[i]+(i==selected?t(", выбрано",", selected"):""));v.setOnClickListener(w->{if(!busy&&!closed)action.accept(index);});row.addView(v,new LinearLayout.LayoutParams(-2,-2));}HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setFillViewport(true);scroll.addView(row);scroll.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{View active=row.getChildAt(selected);if(active.getRight()>scroll.getScrollX()+scroll.getWidth())scroll.scrollTo(active.getRight()-scroll.getWidth(),0);else if(active.getLeft()<scroll.getScrollX())scroll.scrollTo(active.getLeft(),0);});parent.addView(scroll);}
        void select(){selectors.removeAllViews();frame.header.removeAllViews();if(!sessionBound)choices(selectors,new String[]{"Codex","Claude Code"},agent.equals("codex")?0:1,i->{discard();agent=i==0?"codex":"claude";select();load();});selectors.addView(text(AgentInstructionsUi.runtimeNotice(a,environment)));choices(frame.header,new String[]{t("Общие","General"),t("Проектные","Project")},scope.equals("user")?0:1,i->{discard();scope=i==0?"user":"project";select();load();});if(scope.equals("project")&&sessionBound)selectors.addView(text(t("Папка проекта: ","Project folder: ")+project));if(scope.equals("project")&&!sessionBound)button(selectors,t("Папка проекта: ","Project folder: ")+project,()->choose(true,path->{discard();project=path;select();load();}));}
        void call(JSONObject request,Consumer<JSONObject> done){call(request,done,null);}
        void call(JSONObject request,Consumer<JSONObject> done,Consumer<String> failed){if(busy||closed)return;busy=true;dialog.setCancelable(false);status.setText(t("Выполняется операция…","Operation running…"));worker.execute(()->{JSONObject r=null;String error=null;try{r=backend.call(request);}catch(Exception e){error=e.getMessage();}JSONObject result=r;String failure=error;main.post(()->{if(closed)return;busy=false;dialog.setCancelable(true);if(failure!=null){status.setText(t("Операция не завершена. Файлы не заменяются молча. ","Operation did not complete. Files are never silently replaced. ")+error(failure));if(failed!=null)failed.accept(error(failure));}else{status.setText("");done.accept(result);}});});}
        String error(String code){if("INVALID_NAME".equals(code))return t("Имя: 1–64 символа a–z, 0–9 и дефис; первый символ — буква или цифра.","Name: 1–64 lowercase letters, digits or hyphens; start with a letter or digit.");if("INVALID_DESCRIPTION".equals(code))return t("Укажите описание до 1024 символов.","Enter a description of up to 1024 characters.");if("INSTRUCTIONS_REQUIRED".equals(code))return t("Укажите инструкции навыка.","Enter skill instructions.");if("LOCAL_CHANGES".equals(code))return t("Навык изменён локально. Сначала сохраните и сравните изменения.","The skill was modified locally. Preserve and compare your edits first.");if("NAME_CONFLICT".equals(code))return t("Целевой путь уже занят. Откройте установленный навык для явного обновления.","The destination exists. Open the installed skill for an explicit update.");if("UNSUPPORTED_METADATA".equals(code))return t("Этот вариант YAML пока не поддерживается безопасным импортом.","This YAML form is not yet supported by safe import.");return code!=null&&code.matches("[A-Z_]{1,70}")?code:"SKILLS_UNAVAILABLE";}
        void load(){call(q("list"),r->{rows.removeAllViews();rows.addView(text(scope.equals("user")?t("Общие навыки доступны независимо от проекта. Общие каталоги выбранного агента в этой среде:","General skills are available independently of the project. Shared directories for the selected agent in this environment:"):t("Проектные навыки относятся к выбранному проекту. Унаследованные источники отмечены отдельно.","Project skills belong to the selected project. Inherited sources are marked separately.")));JSONArray roots=r.optJSONArray("roots");if(roots!=null)for(int n=0;n<roots.length();n++){JSONObject source=roots.optJSONObject(n);if(source==null)continue;boolean projectSource=source.optString("scope").equals("project")||source.optString("scope").equals("ancestor");if(projectSource!=scope.equals("project"))continue;rows.addView(text(source.optString("path")+" · "+scopeLabel(source.optString("scope"))));}rows.addView(text(t("Установка файлов не подтверждает обнаружение или работу навыка. Скрипты и зависимости не запускаются. Текст ранее использованного навыка может остаться в истории.","Installed files do not prove discovery or functionality. Scripts and dependencies are not run. Previously used skill text can remain in conversation history.")));rows.addView(text(t("Цель установки: ","Install destination: ")+r.optString("target")));JSONArray recovery=r.optJSONArray("recovery");if(recovery!=null)for(int n=0;n<recovery.length();n++){JSONObject p=recovery.optJSONObject(n);if(p!=null)button(rows,t("Восстановить прерванную операцию: ","Recover interrupted operation: ")+p.optString("name"),()->confirm(t("Восстановить состояние пакета?","Recover package state?"),p.optString("path"),()->call(fields(q("recover"),"name",p.optString("name")),v->load())));}JSONArray pending=r.optJSONArray("pending");if(pending!=null)for(int n=0;n<pending.length();n++){JSONObject p=pending.optJSONObject(n);if(p!=null)button(rows,t("Удалить временный предпросмотр…","Discard staged preview…"),()->confirm(t("Удалить только этот временный пакет?","Discard only this staged package?"),p.optString("path"),()->call(fields(q("discard"),"token",p.optString("token")),v->load())));}JSONArray list=r.optJSONArray("skills");if(list==null||list.length()==0)rows.addView(text(t("Навыки не найдены","No skills found")));else for(int i=0;i<list.length();i++){JSONObject item=list.optJSONObject(i);if(item!=null)button(rows,item.optString("name")+"\n"+item.optString("description")+"\n"+item.optString("path"),()->call(fields(q("inspect"),"path",item.optString("path")),v->{java.util.Iterator<String> keys=v.keys();while(keys.hasNext()){String key=keys.next();fields(item,key,v.opt(key));}detail(item);}));}JSONArray errors=r.optJSONArray("errors");if(errors!=null&&errors.length()>0)rows.addView(text(t("Не все источники доступны: ","Some sources are unavailable: ")+errors));});}
        String scopeLabel(String value){switch(value){case "user":return t("Общие","General");case "project":return t("Проектные","Project");case "ancestor":return t("Унаследованные проектные","Inherited project");case "legacy":return t("Общие · прежний каталог","General · legacy directory");case "admin":return t("Общие · системный каталог","General · system directory");case "plugin":return t("Источник плагина","Plugin source");default:return value;}}
        String information(JSONObject item){return (agent.equals("codex")?"Codex":"Claude Code")+" · "+scopeLabel(item.optString("scope",scope))+" · "+item.optString("origin","")+"\n"+item.optString("path")+"\n\n"+item.optString("description")+"\n\n"+t("Источник: ","Source: ")+item.optString("source",t("неизвестен","unknown"))+"\n"+item.optString("commit")+"\n\n"+t("Обнаружение не подтверждено. Функциональная проверка не выполнена.","Discovery unconfirmed. Functionality not checked.")+"\n"+(agent.equals("codex")?t("Codex обновляет список навыков; при отсутствии навыка перезапустите только нужного агента с продолжением диалога.","Codex refreshes its skill list; if absent, restart only the intended agent and resume the conversation."):t("В Claude 2.1.296 добавление подхватывается через /reload-skills. Если навык не появился, используйте /reload-skills в штатном терминале либо явный перезапуск нужного агента. Поведение зависит от версии.","In Claude 2.1.296, /reload-skills discovers added skills. If absent, use /reload-skills in its native terminal or explicitly restart the intended agent. Behavior depends on version."))+"\n\n"+t("Совпадения имён (приоритеты зависят от агента): ","Name collisions (priority is agent-specific): ")+item.optString("nameConflicts")+"\n\n"+(agent.equals("claude")?t("Claude: управляемые → личные → проектные; плагины используют пространство имён.","Claude: managed → personal → project; plugins use namespaces."):t("Codex может показывать навыки с одинаковыми именами отдельно. Проверяйте точный путь.","Codex can list same-name skills separately. Check the exact path."))+"\n\n"+item.optString("error")+"\n\n"+item.optString("text")+"\n\n"+t("Объявления (зависимости не устанавливаются):\n","Declarations (dependencies are not installed):\n")+item.optString("declarations")+"\n\n"+t("Файлы и SHA-256:\n","Files and SHA-256:\n")+item.optString("files")+"\n\n"+t("Скрипты и исполняемые файлы (не запускаются):\n","Scripts and executable files (not run):\n")+item.optString("scripts");}
        void detail(JSONObject item){LinearLayout actions=column();if(item.optBoolean("managed")){button(actions,t("Обновить из источника…","Update from source…"),()->add(true,item));if(item.optBoolean("rollback"))button(actions,t("Откатить предыдущую версию","Restore previous version"),()->confirm(t("Откатить навык?","Restore skill?"),item.optString("path"),()->mutation("rollback",item)));button(actions,t("Удалить…","Delete…"),()->confirm(t("Удалить навык?","Delete skill?"),item.optString("path"),()->mutation("delete",item)));}else actions.addView(text(t("Внешний навык: обновление и удаление выполняет его владелец или менеджер.","External skill: its owner or package manager handles updates and removal.")));preview(item.optString("name"),information(item),actions,null);}
